sed -i 's/        RoleSelectionScreen(/        RoleSelectionScreen(\n            onRoleSelected = { selectedRole ->\n                if (selectedRole == UserRole.MANAGER) {\n                    viewModel.setRole(selectedRole)\n                    showRoleSelection = false\n                } else {\n                    pendingRole = selectedRole\n                    showKeyAuth = true\n                    showRoleSelection = false\n                }\n            }\n        )\n    } else if (showKeyAuth \&\& pendingRole != null) {\n        KeyAuthScreen(\n            role = pendingRole!!,\n            onAuthSuccess = { name ->\n                viewModel.setRole(pendingRole!!)\n                viewModel.setUserName(name)\n                showKeyAuth = false\n            },\n            onCancel = {\n                showKeyAuth = false\n                showRoleSelection = true\n            },\n            validateKey = { key -> viewModel.validateUserKey(key, pendingRole!!) }\n        )\n    } else if (currentRole == UserRole.MANAGER \&\& !isManagerInitialized) {/g' app/src/main/java/com/example/MainActivity.kt
